def ensure_auth_tables():
    """Ensure Main Admin and Teacher account tables exist before /auth/login is used.

    This is intentionally kept in the Server startup path so Render does not depend
    on a local SQLite-only database initializer. Existing tables and credentials are
    preserved; the default admin is created only when no admin row exists.
    """
    with SessionLocal() as db:
        dialect = getattr(getattr(db, "bind", None), "dialect", None)
        dialect_name = getattr(dialect, "name", "")
        is_postgres = dialect_name == "postgresql"

        if is_postgres:
            main_id = "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY"
            teacher_id = "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY"
            active_type = "BOOLEAN NOT NULL DEFAULT TRUE"
            created_type = "TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP"
        else:
            main_id = "INTEGER PRIMARY KEY AUTOINCREMENT"
            teacher_id = "INTEGER PRIMARY KEY AUTOINCREMENT"
            active_type = "INTEGER NOT NULL DEFAULT 1"
            created_type = "TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP"

        db.execute(text(f"""
            CREATE TABLE IF NOT EXISTS main_accounts (
                id {main_id},
                username TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                role TEXT NOT NULL DEFAULT 'MAIN_ADMIN',
                is_active {active_type},
                full_name TEXT NOT NULL DEFAULT 'Main Administrator',
                created_at {created_type}
            )
        """))
        db.execute(text(f"""
            CREATE TABLE IF NOT EXISTS teacher_accounts (
                id {teacher_id},
                main_account_id BIGINT NOT NULL DEFAULT 0,
                username TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                full_name TEXT NOT NULL DEFAULT '',
                is_active {active_type},
                created_at {created_type}
            )
        """))

        main_columns = _table_columns(db, "main_accounts")
        teacher_columns = _table_columns(db, "teacher_accounts")

        # Add missing compatibility columns to older databases without touching data.
        if "role" not in main_columns:
            db.execute(text("ALTER TABLE main_accounts ADD COLUMN role TEXT NOT NULL DEFAULT 'MAIN_ADMIN'"))
        if "is_active" not in main_columns:
            db.execute(text("ALTER TABLE main_accounts ADD COLUMN is_active INTEGER NOT NULL DEFAULT 1"))
        if "full_name" not in main_columns:
            db.execute(text("ALTER TABLE main_accounts ADD COLUMN full_name TEXT NOT NULL DEFAULT 'Main Administrator'"))
        if "created_at" not in main_columns:
            db.execute(text("ALTER TABLE main_accounts ADD COLUMN created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP"))

        if "main_account_id" not in teacher_columns:
            db.execute(text("ALTER TABLE teacher_accounts ADD COLUMN main_account_id INTEGER NOT NULL DEFAULT 0"))
        if "full_name" not in teacher_columns:
            db.execute(text("ALTER TABLE teacher_accounts ADD COLUMN full_name TEXT NOT NULL DEFAULT ''"))
        if "is_active" not in teacher_columns:
            db.execute(text("ALTER TABLE teacher_accounts ADD COLUMN is_active INTEGER NOT NULL DEFAULT 1"))
        if "created_at" not in teacher_columns:
            db.execute(text("ALTER TABLE teacher_accounts ADD COLUMN created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP"))

        exists = db.execute(
            text("SELECT id FROM main_accounts WHERE username = :username LIMIT 1"),
            {"username": "admin"},
        ).first()

        reset_password = str(os.environ.get("GODEYES_RESET_ADMIN_PASSWORD", "")).strip()

        if exists is None:
            now = datetime.now(timezone.utc)
            initial_password = reset_password or "admin123"
            db.execute(
                text("""
                    INSERT INTO main_accounts
                        (username, password_hash, role, is_active, full_name, created_at)
                    VALUES
                        (:username, :password_hash, 'MAIN_ADMIN', :is_active, :full_name, :created_at)
                """),
                {
                    "username": "admin",
                    "password_hash": hash_password(initial_password),
                    "is_active": True if is_postgres else 1,
                    "full_name": "Administrator",
                    "created_at": now if is_postgres else now.isoformat(timespec="seconds"),
                },
            )
        elif reset_password:
            db.execute(
                text("""
                    UPDATE main_accounts
                    SET password_hash = :password_hash,
                        role = 'MAIN_ADMIN',
                        is_active = :is_active
                    WHERE username = 'admin'
                """),
                {
                    "password_hash": hash_password(reset_password),
                    "is_active": True if is_postgres else 1,
                },
            )

        db.commit()


ensure_auth_tables()


# ---------------------------------------------------------------------------
# Unified authentication endpoints
# ---------------------------------------------------------------------------
# The deployed project previously registered /auth/login from routes/auth.py.
# That created a fragile dependency on the ORM model/database generation being
# perfectly aligned. The Server now owns the login endpoint directly and uses
# raw SQL against the SAME SessionLocal/database used by the rest of this file.
# This keeps Admin login compatible with both SQLite (local) and PostgreSQL
# (Render) databases and avoids the mixed auth generations that caused the
# previous Internal Server Error.

@app.post("/auth/login")
def server_login(payload: dict, response: Response):
    username = str(payload.get("username") or "").strip()
    password = str(payload.get("password") or "")

    if not username or not password:
        return JSONResponse(
            {"detail": "Vui lòng nhập tên đăng nhập và mật khẩu."},
            status_code=400,
        )

    try:
        with SessionLocal() as db:
            main_row = db.execute(
                text("""
                    SELECT id, username, password_hash, role, is_active, full_name
                    FROM main_accounts
                    WHERE username = :username
                    LIMIT 1
                """),
                {"username": username},
            ).mappings().first()

            if main_row is not None:
                try:
                    active = bool(main_row["is_active"])
                except Exception:
                    active = str(main_row["is_active"]).strip().lower() in {
                        "1", "true", "t", "yes", "y"
                    }

                if not active:
                    return JSONResponse(
                        {"detail": "Tài khoản đã bị khóa."},
                        status_code=401,
                    )

                try:
                    password_ok = verify_password(
                        password,
                        str(main_row["password_hash"] or ""),
                    )
                except Exception:
                    password_ok = False

                if not password_ok:
                    return JSONResponse(
                        {"detail": "Sai tên đăng nhập hoặc mật khẩu."},
                        status_code=401,
                    )

                role = str(main_row["role"] or "MAIN_ADMIN")
                token = create_access_token(
                    user_id=int(main_row["id"]),
                    username=str(main_row["username"]),
                    role=role,
                )
                response.set_cookie(
                    key="godeyes_access_token",
                    value=token,
                    httponly=True,
                    samesite="lax",
                    secure=True,
                    max_age=3600,
                    path="/",
                )
                return {
                    "access_token": token,
                    "token_type": "bearer",
                    "username": str(main_row["username"]),
                    "role": role,
                    "full_name": str(main_row["full_name"] or main_row["username"]),
                }

            teacher_row = db.execute(
                text("""
                    SELECT id, username, password_hash, full_name, is_active
                    FROM teacher_accounts
                    WHERE username = :username
                    LIMIT 1
                """),
                {"username": username},
            ).mappings().first()

            if teacher_row is not None:
                try:
                    active = bool(teacher_row["is_active"])
                except Exception:
                    active = str(teacher_row["is_active"]).strip().lower() in {
                        "1", "true", "t", "yes", "y"
                    }

                if not active:
                    return JSONResponse(
                        {"detail": "Tài khoản đã bị khóa."},
                        status_code=401,
                    )

                try:
                    password_ok = verify_password(
                        password,
                        str(teacher_row["password_hash"] or ""),
                    )
                except Exception:
                    password_ok = False

                if not password_ok:
                    return JSONResponse(
                        {"detail": "Sai tên đăng nhập hoặc mật khẩu."},
                        status_code=401,
                    )

                token = create_access_token(
                    user_id=int(teacher_row["id"]),
                    username=str(teacher_row["username"]),
                    role="TEACHER",
                )
                response.set_cookie(
                    key="godeyes_access_token",
                    value=token,
                    httponly=True,
                    samesite="lax",
                    secure=True,
                    max_age=3600,
                    path="/",
                )
                return {
                    "access_token": token,
                    "token_type": "bearer",
                    "username": str(teacher_row["username"]),
                    "role": "TEACHER",
                    "full_name": str(teacher_row["full_name"] or teacher_row["username"]),
                }

    except Exception as exc:
        # Do not leak database internals to the browser. Return a controlled
        # service error so the real cause can be investigated without the UI
        # collapsing into a generic unhandled 500.
        return JSONResponse(
            {
                "detail": "Không thể xử lý đăng nhập trên Server. Vui lòng thử lại sau.",
                "error_type": type(exc).__name__,
            },
            status_code=503,
        )

    return JSONResponse(
        {"detail": "Sai tên đăng nhập hoặc mật khẩu."},
        status_code=401,
    )


