MAIN_CAMERA_SECRET_LABEL = b"GodEyesMainCameraV31"

def _camera_fernet():
    if Fernet is None:
        return None
    raw = os.environ.get("GODEYES_JWT_SECRET", "GodEyes-Local-Secret-Change-Later").encode("utf-8")
    import hashlib as _hashlib
    key = urlsafe_b64encode(_hashlib.sha256(raw + MAIN_CAMERA_SECRET_LABEL).digest())
    return Fernet(key)

def _encrypt_camera_secret(value: str) -> str:
    value = str(value or "")
    f = _camera_fernet()
    if f is None:
        return value
    return f.encrypt(value.encode("utf-8")).decode("ascii")

def _decrypt_camera_secret(value: str) -> str:
    value = str(value or "")
    if not value:
        return ""
    f = _camera_fernet()
    if f is None:
        return value
    try:
        return f.decrypt(value.encode("ascii")).decode("utf-8")
    except Exception:
        return value

