def _camera_profile_dict(row, include_url=False):
    item = {
        "id": int(row["id"]),
        "name": row["name"],
        "brand": row["brand"],
        "model": row["model"],
        "source_type": row["source_type"],
        "device_id": row["device_id"],
        "host": row["host"],
        "port": int(row["port"] or 554),
        "stream": row["stream"],
        "username": row["username"],
        "last_verified_at": row["last_verified_at"],
    }
    if include_url and row["source_type"] == "wifi_camera" and row["host"] and row["username"]:
        from urllib.parse import quote as _quote
        pwd = _decrypt_camera_secret(row["password_enc"])
        item["rtsp_url"] = f"rtsp://{_quote(str(row['username']), safe='')}:{_quote(str(pwd), safe='')}@{row['host']}:{int(row['port'] or 554)}/{row['stream']}"
    else:
        item["rtsp_url"] = ""
    return item


def _normalise_main_camera_payload(body):
    source = str(body.get("source_type") or "wifi_camera").strip().lower()
    if source not in {"webcam", "usb", "wifi_camera"}: source = "wifi_camera"
    brand = str(body.get("brand") or "").strip().lower()[:40]
    model = str(body.get("model") or "").strip()[:80]
    name = str(body.get("name") or "").strip()[:120]
    host = str(body.get("host") or "").strip()[:120]
    username = str(body.get("username") or "").strip()[:120]
    password = str(body.get("password") or "")
    device_id = str(body.get("device_id") or "").strip()[:180]
    stream = str(body.get("stream") or "stream1").strip().lower()
    if stream not in {"stream1", "stream2"}: stream = "stream1"
    try: port = max(1, min(65535, int(body.get("port") or 554)))
    except Exception: port = 554
    return {"source_type":source,"brand":brand,"model":model,"name":name,"host":host,"port":port,"stream":stream,"username":username,"password":password,"device_id":device_id}


def _hash_device_token(token: str) -> str:
    return hashlib.sha256(str(token).encode('utf-8')).hexdigest()


