def ensure_teacher_preferences_table():
    # Per-teacher settings shared by Teacher Web and God Eyes Desktop.
    # Additive migration only. Existing data is preserved.
    with SessionLocal() as db:
        db.execute(text("""
            CREATE TABLE IF NOT EXISTS teacher_preferences (
                teacher_id INTEGER PRIMARY KEY,
                language TEXT NOT NULL DEFAULT 'vi',
                theme TEXT NOT NULL DEFAULT 'light',
                camera_source TEXT NOT NULL DEFAULT 'webcam',
                camera_brand TEXT NOT NULL DEFAULT '',
                camera_device_index INTEGER NOT NULL DEFAULT 0,
                camera_host TEXT NOT NULL DEFAULT '',
                camera_port INTEGER NOT NULL DEFAULT 554,
                camera_stream TEXT NOT NULL DEFAULT 'stream1',
                camera_username TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP::text
            )
        """))
        columns = _table_columns(db, "teacher_preferences")
        migrations = {
            'camera_source': "ALTER TABLE teacher_preferences ADD COLUMN camera_source TEXT NOT NULL DEFAULT 'webcam'",
            'camera_brand': "ALTER TABLE teacher_preferences ADD COLUMN camera_brand TEXT NOT NULL DEFAULT ''",
            'camera_device_index': "ALTER TABLE teacher_preferences ADD COLUMN camera_device_index INTEGER NOT NULL DEFAULT 0",
            'camera_host': "ALTER TABLE teacher_preferences ADD COLUMN camera_host TEXT NOT NULL DEFAULT ''",
            'camera_port': "ALTER TABLE teacher_preferences ADD COLUMN camera_port INTEGER NOT NULL DEFAULT 554",
            'camera_stream': "ALTER TABLE teacher_preferences ADD COLUMN camera_stream TEXT NOT NULL DEFAULT 'stream1'",
            'camera_username': "ALTER TABLE teacher_preferences ADD COLUMN camera_username TEXT NOT NULL DEFAULT ''",
        }
        for column, ddl in migrations.items():
            if column not in columns:
                db.execute(text(ddl))
        db.execute(text("CREATE INDEX IF NOT EXISTS idx_teacher_preferences_updated ON teacher_preferences(updated_at DESC)"))
        db.commit()


def _normalise_teacher_preferences(language='vi', theme='light', camera_source='webcam', camera_brand='',
                                   camera_device_index=0, camera_host='', camera_port=554,
                                   camera_stream='stream1', camera_username='') -> dict:
    language = str(language or 'vi').strip().lower()
    theme = str(theme or 'light').strip().lower()
    source = str(camera_source or 'webcam').strip().lower()
    brand = str(camera_brand or '').strip().lower()
    if language not in {'vi', 'en'}:
        language = 'vi'
    if theme not in {'light', 'dark'}:
        theme = 'light'
    source_aliases = {
        'usb_webcam': 'usb', 'usb': 'usb', 'webcam': 'webcam',
        'wifi_camera': 'wifi_camera', 'wifi': 'wifi_camera', 'wireless_camera': 'wifi_camera',
        'tapo': 'wifi_camera', 'tapo_c230': 'wifi_camera', 'rtsp': 'wifi_camera',
        'tapo_c230_rtsp': 'wifi_camera',
    }
    source = source_aliases.get(source, 'webcam')
    if source == 'wifi_camera':
        if not brand:
            brand = 'tapo'
    else:
        brand = ''
    try:
        device_index = max(0, min(9, int(camera_device_index)))
    except (TypeError, ValueError):
        device_index = 0
    try:
        port = max(1, min(65535, int(camera_port)))
    except (TypeError, ValueError):
        port = 554
    stream = str(camera_stream or 'stream1').strip().lower()
    if stream not in {'stream1', 'stream2'}:
        stream = 'stream1'
    return {
        'language': language,
        'theme': theme,
        'camera_source': source,
        'camera_brand': brand[:40],
        'camera_device_index': device_index,
        'camera_host': str(camera_host or '').strip(),
        'camera_port': port,
        'camera_stream': stream,
        'camera_username': str(camera_username or '').strip()[:120],
    }


