def _teacher_localize_text(value: str, language: str) -> str:
    text = str(value or '')
    if language == 'en':
        mapping = dict(TEACHER_I18N_VI_EN)
        mapping.update(STRICT_VI_TO_EN)
    else:
        mapping = {v: k for k, v in TEACHER_I18N_VI_EN.items() if v != k}
        mapping.update(TEACHER_I18N_EN_VI_EXTRA)
        mapping.update(STRICT_EN_TO_VI)
    if not text.strip():
        return text
    for src, dst in sorted(mapping.items(), key=lambda kv: len(kv[0]), reverse=True):
        if src and src in text:
            text = text.replace(src, dst)
    return text


def _teacher_localize_html(html: str, language: str) -> str:
    # Translate visible text and common form attributes while leaving student/class data intact.
    def repl_text(m):
        return m.group(1) + _teacher_localize_text(m.group(2), language) + m.group(3)
    # Text between tags. Avoid script/style blocks.
    chunks = re.split(r'(<(?:script|style)\b.*?</(?:script|style)>)', html, flags=re.I | re.S)
    for i in range(0, len(chunks), 2):
        chunks[i] = re.sub(r'(>)([^<>]{1,400})(<)', repl_text, chunks[i])
        chunks[i] = re.sub(r'((?:placeholder|title|aria-label|alt|onsubmit)=\\?\")([^\"]{1,400})(\")',
                           lambda m: m.group(1) + _teacher_localize_text(m.group(2), language) + m.group(3), chunks[i])
        chunks[i] = re.sub(r"((?:placeholder|title|aria-label|alt|onsubmit)=')([^']{1,400})(')",
                           lambda m: m.group(1) + _teacher_localize_text(m.group(2), language) + m.group(3), chunks[i])
    return ''.join(chunks)


def get_teacher_preferences(teacher_id: int) -> dict:
    defaults = _normalise_teacher_preferences()
    with SessionLocal() as db:
        row = db.execute(
            text("""
                SELECT language, theme, camera_source, camera_brand, camera_device_index,
                       camera_host, camera_port, camera_stream, camera_username
                FROM teacher_preferences
                WHERE teacher_id = :teacher_id
                LIMIT 1
            """),
            {'teacher_id': int(teacher_id)}
        ).mappings().first()
        if row is None:
            db.execute(text("""
                INSERT INTO teacher_preferences
                    (teacher_id, language, theme, camera_source, camera_brand, camera_device_index,
                     camera_host, camera_port, camera_stream, camera_username, updated_at)
                VALUES
                    (:teacher_id, :language, :theme, :camera_source, :camera_brand, :camera_device_index,
                     :camera_host, :camera_port, :camera_stream, :camera_username, :updated_at)
            """), {
                'teacher_id': int(teacher_id), **defaults,
                'updated_at': datetime.now(timezone.utc).isoformat(timespec='seconds'),
            })
            db.commit()
            return defaults
        return _normalise_teacher_preferences(
            row['language'], row['theme'], row['camera_source'], row['camera_brand'],
            row['camera_device_index'], row['camera_host'], row['camera_port'],
            row['camera_stream'], row['camera_username']
        )


def save_teacher_preferences(teacher_id: int, language=None, theme=None, camera_source=None,
                              camera_brand=None, camera_device_index=None, camera_host=None,
                              camera_port=None, camera_stream=None, camera_username=None) -> dict:
    current = get_teacher_preferences(int(teacher_id))
    prefs = _normalise_teacher_preferences(
        current['language'] if language is None else language,
        current['theme'] if theme is None else theme,
        current['camera_source'] if camera_source is None else camera_source,
        current['camera_brand'] if camera_brand is None else camera_brand,
        current['camera_device_index'] if camera_device_index is None else camera_device_index,
        current['camera_host'] if camera_host is None else camera_host,
        current['camera_port'] if camera_port is None else camera_port,
        current['camera_stream'] if camera_stream is None else camera_stream,
        current['camera_username'] if camera_username is None else camera_username,
    )
    now = datetime.now(timezone.utc).isoformat(timespec='seconds')
    with SessionLocal() as db:
        row = db.execute(
            text("SELECT teacher_id FROM teacher_preferences WHERE teacher_id = :teacher_id LIMIT 1"),
            {'teacher_id': int(teacher_id)}
        ).first()
        params = {'teacher_id': int(teacher_id), **prefs, 'updated_at': now}
        if row is None:
            db.execute(text("""
                INSERT INTO teacher_preferences
                    (teacher_id, language, theme, camera_source, camera_brand, camera_device_index,
                     camera_host, camera_port, camera_stream, camera_username, updated_at)
                VALUES
                    (:teacher_id, :language, :theme, :camera_source, :camera_brand, :camera_device_index,
                     :camera_host, :camera_port, :camera_stream, :camera_username, :updated_at)
            """), params)
        else:
            db.execute(text("""
                UPDATE teacher_preferences
                SET language=:language,
                    theme=:theme,
                    camera_source=:camera_source,
                    camera_brand=:camera_brand,
                    camera_device_index=:camera_device_index,
                    camera_host=:camera_host,
                    camera_port=:camera_port,
                    camera_stream=:camera_stream,
                    camera_username=:camera_username,
                    updated_at=:updated_at
                WHERE teacher_id=:teacher_id
            """), params)
        db.commit()
    return prefs


ensure_teacher_preferences_table()


def _issue_persistent_device_token(db, teacher_id: int, device_label: str = 'God Eyes Desktop', app_version: str = DESKTOP_APP_VERSION) -> str:
    raw = secrets.token_urlsafe(APP_DEVICE_TOKEN_BYTES)
    token_hash = _hash_device_token(raw)
    db.execute(
        text("""
            INSERT INTO app_devices
                (teacher_id, token_hash, device_label, app_version, created_at, last_used_at, revoked_at)
            VALUES
                (:teacher_id, :token_hash, :device_label, :app_version, :created_at, :last_used_at, '')
        """),
        {
            'teacher_id': int(teacher_id),
            'token_hash': token_hash,
            'device_label': str(device_label or 'God Eyes Desktop')[:120],
            'app_version': str(app_version or '')[:40],
            'created_at': utc_now_iso() if 'utc_now_iso' in globals() else datetime.now(timezone.utc).isoformat(timespec='seconds'),
            'last_used_at': utc_now_iso() if 'utc_now_iso' in globals() else datetime.now(timezone.utc).isoformat(timespec='seconds'),
        }
    )
    return raw


def _exchange_persistent_device_token(token: str):
    token_hash = _hash_device_token(token)
    now = datetime.now(timezone.utc).isoformat(timespec='seconds')
    with SessionLocal() as db:
        row = db.execute(
            text("""
                SELECT d.id, d.teacher_id, t.username, t.full_name, t.is_active
                FROM app_devices d
                JOIN teacher_accounts t ON t.id = d.teacher_id
                WHERE d.token_hash = :token_hash
                  AND d.revoked_at = ''
                LIMIT 1
            """),
            {'token_hash': token_hash}
        ).mappings().first()
        if row is None:
            return None
        if not row['is_active']:
            return None
        db.execute(
            text("UPDATE app_devices SET last_used_at = :now WHERE id = :id"),
            {'now': now, 'id': int(row['id'])}
        )
        db.commit()
        access_token = create_access_token(
            user_id=int(row['teacher_id']),
            username=row['username'],
            role='TEACHER'
        )
        return {
            'access_token': access_token,
            'token_type': 'bearer',
            'username': row['username'],
            'role': 'TEACHER',
            'full_name': row['full_name'],
            'client_version': DESKTOP_APP_VERSION,
        }


def _revoke_persistent_device_token(token: str, teacher_id: int | None = None) -> bool:
    token_hash = _hash_device_token(token)
    params = {'token_hash': token_hash}
    where = 'token_hash = :token_hash AND revoked_at = '''
    if teacher_id is not None:
        where += ' AND teacher_id = :teacher_id'
        params['teacher_id'] = int(teacher_id)
    with SessionLocal() as db:
        result = db.execute(
            text(f"UPDATE app_devices SET revoked_at = :revoked_at WHERE {where}"),
            {**params, 'revoked_at': datetime.now(timezone.utc).isoformat(timespec='seconds')}
        )
        db.commit()
        return result.rowcount > 0


def _find_god_eyes_app():
    # Prefer an explicit path, then common local development / packaged paths.
    configured = str(os.environ.get('GODEYES_APP_PATH', '')).strip()
    candidates = []
    if configured:
        candidates.append(Path(configured).expanduser())
    candidates.extend([
        Path(r'D:\GodEyes\dist\GodEyes.exe'),
        Path(r'D:\GodEyes\app\main.py'),
        Path.home() / 'Downloads' / 'GodEyes' / 'app' / 'main.py',
        Path.home() / 'Downloads' / 'GodEyes' / 'dist' / 'GodEyes.exe',
        APP_DIR.parent / 'GodEyes' / 'app' / 'main.py',
        APP_DIR / 'GodEyes' / 'app' / 'main.py',
    ])
    seen = set()
    for candidate in candidates:
        try:
            candidate = candidate.resolve()
            key = str(candidate).lower()
        except Exception:
            continue
        if key in seen:
            continue
        seen.add(key)
        if candidate.exists() and candidate.is_file():
            return candidate
    return None


def _cleanup_face_scan_tokens():
    now = time.time()
    expired = [key for key, value in FACE_SCAN_TOKENS.items()
               if float(value.get('expires_at', 0.0)) <= now]
    for key in expired:
        FACE_SCAN_TOKENS.pop(key, None)


def _issue_face_scan_token(student_id: int, admin_id: int) -> str:
    _cleanup_face_scan_tokens()
    token = secrets.token_urlsafe(32)
    FACE_SCAN_TOKENS[token] = {
        'student_id': int(student_id),
        'admin_id': int(admin_id),
        'expires_at': time.time() + FACE_SCAN_TOKEN_TTL,
    }
    return token


def ensure_student_tables():
    """Create student profile and class membership tables for local development."""
    with SessionLocal() as db:
        db.execute(text("""
            CREATE TABLE IF NOT EXISTS students (
                id BIGSERIAL PRIMARY KEY,
                owner_type TEXT NOT NULL DEFAULT 'TEACHER',
                owner_id INTEGER NOT NULL,
                student_code TEXT NOT NULL,
                full_name TEXT NOT NULL,
                photo_path TEXT NOT NULL DEFAULT '',
                face_status TEXT NOT NULL DEFAULT 'NO_DATA',
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP::text,
                updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP::text
            )
        """))
        db.execute(text("""
            CREATE TABLE IF NOT EXISTS class_students (
                id BIGSERIAL PRIMARY KEY,
                class_id INTEGER NOT NULL,
                student_id INTEGER NOT NULL,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP::text,
                UNIQUE (class_id, student_id)
            )
        """))
        columns = _table_columns(db, "students")
        if "face_embedding" not in columns:
            db.execute(text("ALTER TABLE students ADD COLUMN face_embedding TEXT NOT NULL DEFAULT ''"))
        db.execute(text("CREATE INDEX IF NOT EXISTS idx_students_owner ON students(owner_type, owner_id)"))
        db.execute(text("CREATE INDEX IF NOT EXISTS idx_class_students_class ON class_students(class_id)"))
        db.execute(text("CREATE INDEX IF NOT EXISTS idx_class_students_student ON class_students(student_id)"))
        db.commit()


ensure_student_tables()


