@app.post("/admin/accounts/create")
def create_teacher_page(
    request: Request,
    full_name: str = Form(...),
    username: str = Form(...),
    password: str = Form(...)
):
    payload = get_admin_payload(request)

    if payload is None:
        return RedirectResponse(url="/", status_code=303)

    username = username.strip()
    full_name = full_name.strip()

    if not username or not full_name or len(password) < 8:
        return RedirectResponse(
            url="/admin/accounts/new",
            status_code=303
        )

    with SessionLocal() as db:
        existing = db.scalar(
            select(TeacherAccount).where(
                TeacherAccount.username == username
            )
        )

        if existing:
            return RedirectResponse(
                url="/admin?section=accounts&error=exists",
                status_code=303
            )

        teacher = TeacherAccount(
            main_account_id=int(payload["sub"]),
            username=username,
            password_hash=hash_password(password),
            full_name=full_name,
            is_active=True,
            created_at=datetime.now()
        )

        db.add(teacher)
        try:
            db.commit()
        except Exception:
            db.rollback()
            return RedirectResponse(
                url="/admin/accounts/new?error=create_failed",
                status_code=303
            )

    return RedirectResponse(
        url="/admin?section=accounts&created=1",
        status_code=303
    )


