def generate_student_code(db, class_id: int) -> str:
    for _ in range(50):
        code = "HS-" + "".join(secrets.choice(string.digits) for _ in range(6))
        exists = db.scalar(
            text("""
                SELECT s.id
                FROM students s
                JOIN class_students cs ON cs.student_id = s.id
                WHERE cs.class_id = :class_id AND s.student_code = :code
                LIMIT 1
            """),
            {"class_id": class_id, "code": code}
        )
        if exists is None:
            return code
    raise RuntimeError("Không thể tạo mã học sinh mới.")


def _load_face_models():
    if not YUNET_MODEL_PATH.exists():
        raise FileNotFoundError(f"Missing YuNet model: {YUNET_MODEL_PATH}")
    if not SFACE_MODEL_PATH.exists():
        raise FileNotFoundError(f"Missing SFace model: {SFACE_MODEL_PATH}")
    if not hasattr(cv2, "FaceDetectorYN"):
        raise RuntimeError("OpenCV FaceDetectorYN is not available.")
    if not hasattr(cv2, "FaceRecognizerSF"):
        raise RuntimeError("OpenCV FaceRecognizerSF is not available. Please use OpenCV 4.10+.")
    detector = cv2.FaceDetectorYN.create(
        str(YUNET_MODEL_PATH),
        "",
        (320, 320),
        FACE_DETECTION_SCORE_THRESHOLD,
        FACE_NMS_THRESHOLD,
        5000,
        cv2.dnn.DNN_BACKEND_OPENCV,
        cv2.dnn.DNN_TARGET_CPU,
    )
    recognizer = cv2.FaceRecognizerSF.create(
        str(SFACE_MODEL_PATH),
        "",
        cv2.dnn.DNN_BACKEND_OPENCV,
        cv2.dnn.DNN_TARGET_CPU,
    )
    return detector, recognizer


def _read_student_image(path_value: str):
    if not path_value:
        raise ValueError("no_photo")
    try:
        data = Path(path_value).read_bytes()
    except OSError:
        raise ValueError("invalid_image")
    image = cv2.imdecode(np.frombuffer(data, dtype=np.uint8), cv2.IMREAD_COLOR)
    if image is None or image.size == 0:
        raise ValueError("invalid_image")
    return image


def _prepare_face_image(image):
    h, w = image.shape[:2]
    if h <= 0 or w <= 0:
        raise ValueError("invalid_image")
    longest = max(h, w)
    if longest > FACE_MAX_IMAGE_SIDE:
        scale = FACE_MAX_IMAGE_SIDE / float(longest)
        new_w = max(1, int(round(w * scale)))
        new_h = max(1, int(round(h * scale)))
        image = cv2.resize(image, (new_w, new_h), interpolation=cv2.INTER_AREA)
    return image


def _detect_face_yunet(image, detector):
    h, w = image.shape[:2]
    detector.setInputSize((w, h))
    _, faces = detector.detect(image)
    if faces is None:
        return []
    return list(faces)


def _select_reference_face(image, faces):
    if len(faces) == 0:
        raise ValueError("no_face")
    if len(faces) > 1:
        raise ValueError("multiple_faces")

    face = np.asarray(faces[0], dtype=np.float32)
    x, y, width, height = [float(v) for v in face[:4]]
    image_h, image_w = image.shape[:2]
    if image_w <= 0 or image_h <= 0 or width <= 0 or height <= 0:
        raise ValueError("invalid_image")

    score = float(face[-1]) if face.size >= 15 else 1.0
    if score < FACE_DETECTION_SCORE_THRESHOLD:
        raise ValueError("no_face")

    x1 = max(0.0, min(x, image_w - 1.0))
    y1 = max(0.0, min(y, image_h - 1.0))
    x2 = max(x1 + 1.0, min(x + width, float(image_w)))
    y2 = max(y1 + 1.0, min(y + height, float(image_h)))
    clipped_w = x2 - x1
    clipped_h = y2 - y1
    face_area_ratio = (clipped_w * clipped_h) / float(image_w * image_h)
    if face_area_ratio < FACE_MIN_AREA_RATIO:
        raise ValueError("face_too_small")

    face[:4] = [x1, y1, clipped_w, clipped_h]
    return face


def generate_face_embedding(path_value: str) -> list[float]:
    image = _prepare_face_image(_read_student_image(path_value))
    detector, recognizer = _load_face_models()
    faces = _detect_face_yunet(image, detector)
    face = _select_reference_face(image, faces)

    try:
        aligned = recognizer.alignCrop(image, face)
        feature = recognizer.feature(aligned)
    except cv2.error as exc:
        raise RuntimeError("face_embedding_error") from exc

    vector = np.asarray(feature, dtype=np.float32).reshape(-1)
    if vector.size == 0:
        raise RuntimeError("empty_embedding")
    norm = float(np.linalg.norm(vector))
    if norm <= 1e-8:
        raise RuntimeError("empty_embedding")
    vector = vector / norm
    return [float(v) for v in vector]


def save_face_embedding(db, student_id: int, embedding: list[float]):
    db.execute(
        text("""
            UPDATE students
            SET face_embedding = :face_embedding,
                face_status = 'READY',
                updated_at = CURRENT_TIMESTAMP
            WHERE id = :student_id
        """),
        {"face_embedding": json.dumps(embedding, separators=(",", ":")), "student_id": student_id}
    )


def analyze_student_photo_for_db(db, student_id: int, path_value: str) -> str:
    embedding = generate_face_embedding(path_value)
    save_face_embedding(db, student_id, embedding)
    return "READY"


def mark_face_review(db, student_id: int):
    db.execute(
        text("""
            UPDATE students
            SET face_status = 'REVIEW',
                face_embedding = '',
                updated_at = CURRENT_TIMESTAMP
            WHERE id = :student_id
        """),
        {"student_id": student_id}
    )

def face_validation_notice(code: str) -> tuple[str, str]:
    notices = {
        "no_face": ("Không phát hiện được khuôn mặt. Hãy dùng ảnh rõ mặt, chỉ có một học sinh.", "error"),
        "multiple_faces": ("Ảnh có nhiều hơn một khuôn mặt. Hãy dùng ảnh chỉ có một học sinh.", "error"),
        "face_too_small": ("Khuôn mặt trong ảnh quá nhỏ. Hãy chọn ảnh cận mặt hơn.", "error"),
        "invalid_image": ("Không thể đọc ảnh. Vui lòng chọn lại ảnh JPG, PNG hoặc WEBP.", "error"),
        "face_embedding_error": ("Chưa tạo được Face ID từ ảnh này. Ảnh vẫn được giữ lại để bạn đổi ảnh hoặc thử tạo lại.", "error"),
    }
    return notices.get(code, ("", ""))


def save_student_photo(photo: UploadFile) -> str:
    allowed_types = {"image/jpeg": ".jpg", "image/png": ".png", "image/webp": ".webp"}
    suffix = allowed_types.get((photo.content_type or "").lower())
    if suffix is None:
        raise ValueError("Chỉ chấp nhận ảnh JPG, PNG hoặc WEBP.")

    data = photo.file.read()
    if len(data) > 5 * 1024 * 1024:
        raise ValueError("Ảnh học sinh không được vượt quá 5 MB.")

    filename = f"{uuid.uuid4().hex}{suffix}"
    destination = STUDENT_PHOTO_DIR / filename
    destination.write_bytes(data)
    return str(destination)


def remove_student_photo(path_value: str):
    if not path_value:
        return
    try:
        Path(path_value).unlink(missing_ok=True)
    except OSError:
        pass


def student_face_label(status: str) -> tuple[str, str]:
    labels = {
        "NO_DATA": ("Chưa có dữ liệu khuôn mặt", "neutral"),
        "PENDING": ("Đã có ảnh · chờ phân tích", "pending"),
        "READY": ("Đã sẵn sàng nhận diện", "ready"),
        "REVIEW": ("Cần kiểm tra lại", "review"),
    }
    return labels.get(status, labels["NO_DATA"])


def student_avatar(row) -> str:
    if row["photo_path"]:
        filename = Path(row["photo_path"]).name
        return f'<div class="student-avatar"><img src="/teacher/student-photo/{escape(filename)}" alt="Ảnh học sinh"></div>'
    initial = escape((row["full_name"] or "H").strip()[:1].upper())
    return f'<div class="student-avatar student-avatar-empty">{initial}</div>'


@app.get("/teacher/student-photo/{filename}")
def teacher_student_photo(request: Request, filename: str):
    from fastapi.responses import FileResponse

    payload = get_teacher_payload(request)
    if payload is None:
        return RedirectResponse(url="/", status_code=303)

    safe_name = Path(filename).name
    file_path = STUDENT_PHOTO_DIR / safe_name
    if not file_path.exists():
        return RedirectResponse(url="/teacher?section=students", status_code=303)

    teacher_id = int(payload["sub"])
    with SessionLocal() as db:
        # The existing database may contain Windows paths while Render runs on Linux.
        # Authorize by normalized filename so the photo remains accessible after deployment.
        allowed = db.scalar(
            text("""
                SELECT s.id
                FROM students s
                WHERE s.owner_type = 'TEACHER'
                  AND s.owner_id = :teacher_id
                  AND lower(replace(s.photo_path, '\\', '/')) LIKE :photo_match
                LIMIT 1
            """),
            {"teacher_id": teacher_id, "photo_match": "%" + safe_name.lower()}
        )

    if allowed is None:
        return RedirectResponse(url="/teacher?section=students", status_code=303)

    return FileResponse(str(file_path))


@app.post("/teacher/students/create")
def create_student(request: Request, class_id: int = Form(...), full_name: str = Form(...), student_code: str = Form(""), photo: UploadFile | None = File(None)):
    payload=get_teacher_payload(request)
    if payload is None: return RedirectResponse(url="/", status_code=303)
    teacher_id=int(payload["sub"]); full_name=full_name.strip(); student_code=student_code.strip().upper()
    if not full_name: return RedirectResponse(url="/teacher?section=students", status_code=303)
    new_photo_path=""
    try:
        with SessionLocal() as db:
            if class_belongs_to_teacher(db,class_id,teacher_id) is None: return RedirectResponse(url="/teacher?section=students", status_code=303)
            if not student_code: student_code=generate_student_code(db,class_id)
            dup=db.scalar(text("SELECT s.id FROM students s JOIN class_students cs ON cs.student_id=s.id WHERE cs.class_id=:class_id AND UPPER(s.student_code)=:student_code LIMIT 1"), {"class_id":class_id,"student_code":student_code})
            if dup is not None: return RedirectResponse(url=f"/teacher?section=students&class_id={class_id}&error=code",status_code=303)
            if photo is not None and photo.filename: new_photo_path=save_student_photo(photo)
            result=db.execute(text("INSERT INTO students (owner_type,owner_id,student_code,full_name,photo_path,face_status,face_embedding) VALUES ('TEACHER',:owner_id,:student_code,:full_name,:photo_path,:face_status,'') RETURNING id"), {"owner_id":teacher_id,"student_code":student_code,"full_name":full_name,"photo_path":new_photo_path,"face_status":"PENDING" if new_photo_path else "NO_DATA"})
            student_id=int(result.scalar_one())
            db.execute(text("INSERT INTO class_students (class_id,student_id) VALUES (:class_id,:student_id)"), {"class_id":class_id,"student_id":student_id})
            if new_photo_path:
                try: analyze_student_photo_for_db(db,student_id,new_photo_path)
                except FileNotFoundError:
                    mark_face_review(db, student_id); db.commit(); return RedirectResponse(url=f"/teacher?section=students&class_id={class_id}&status=face_model_missing",status_code=303)
                except ValueError as exc:
                    code=str(exc) if str(exc) in {"no_face","multiple_faces","face_too_small","invalid_image","face_embedding_error"} else "face_embedding_error"
                    mark_face_review(db, student_id); db.commit(); return RedirectResponse(url=f"/teacher?section=students&class_id={class_id}&status={code}",status_code=303)
                except (RuntimeError,cv2.error):
                    mark_face_review(db, student_id); db.commit(); return RedirectResponse(url=f"/teacher?section=students&class_id={class_id}&status=face_embedding_error",status_code=303)
            db.commit()
    except ValueError:
        remove_student_photo(new_photo_path); return RedirectResponse(url=f"/teacher?section=students&class_id={class_id}&error=photo",status_code=303)
    except Exception:
        remove_student_photo(new_photo_path); raise
    return RedirectResponse(url=f"/teacher?section=students&class_id={class_id}&status={'face_ready' if new_photo_path else 'created'}",status_code=303)


