@app.post("/admin/data/history/trash")
def admin_history_trash(request: Request, session_id: int = Form(...)):
    payload = get_admin_payload(request)
    if payload is None:
        return RedirectResponse(url="/", status_code=303)

    with SessionLocal() as db:
        row = db.execute(
            text("SELECT id, status FROM sessions WHERE id = :session_id AND COALESCE(deleted_at, '') = '' LIMIT 1"),
            {"session_id": session_id}
        ).mappings().first()
        if row is None:
            return RedirectResponse(url="/admin?section=data&view=history", status_code=303)
        if row["status"] == "RUNNING":
            return RedirectResponse(url="/admin?section=data&view=history", status_code=303)
        db.execute(
            text("""
                UPDATE sessions
                SET deleted_at = :deleted_at,
                    deleted_by_teacher_id = 0,
                    deleted_by_username = 'MAIN_ADMIN',
                    deleted_from = 'MAIN_ADMIN'
                WHERE id = :session_id
            """),
            {"deleted_at": utc_now_iso(), "session_id": session_id}
        )
        db.commit()
    return RedirectResponse(url="/admin?section=data&view=history", status_code=303)


