def _find_god_eyes_exe():
    configured = str(os.environ.get('GODEYES_APP_EXE_PATH', '')).strip()
    candidates = []
    if configured:
        candidates.append(Path(configured).expanduser())
    candidates.extend([
        Path(r'D:\GodEyes\dist\GodEyes.exe'),
        Path(r'D:\GodEyes\GodEyes.exe'),
        Path.home() / 'Downloads' / 'GodEyes' / 'dist' / 'GodEyes.exe',
        APP_DIR.parent / 'GodEyes' / 'dist' / 'GodEyes.exe',
    ])
    seen = set()
    for candidate in candidates:
        try:
            candidate = candidate.resolve()
            key = str(candidate).lower()
        except Exception:
            continue
        if key in seen:
            continue
        seen.add(key)
        if candidate.exists() and candidate.is_file() and candidate.suffix.lower() == '.exe':
            return candidate
    return None


def _cleanup_app_launch_tokens():
    now = time.time()
    expired = [key for key, value in APP_LAUNCH_TOKENS.items()
               if float(value.get('expires_at', 0.0)) <= now]
    for key in expired:
        APP_LAUNCH_TOKENS.pop(key, None)


def _issue_app_launch_token(teacher_id: int) -> str:
    _cleanup_app_launch_tokens()
    token = secrets.token_urlsafe(32)
    APP_LAUNCH_TOKENS[token] = {
        'teacher_id': int(teacher_id),
        'expires_at': time.time() + APP_LAUNCH_TOKEN_TTL,
    }
    return token


