@app.get("/local-launch")
def local_launch_app(server_url: str = "https://godeyes-server.onrender.com"):
    """Open the desktop God Eyes app on the local Windows machine.

    This endpoint is intentionally bound to the local server in normal use:
    the browser button on the Render site points to 127.0.0.1:8000.
    The local GodEyesServer finds the installed EXE and launches it with the
    public Render URL so the desktop app connects to the cloud server.
    """
    allowed = "https://godeyes-server.onrender.com"
    if str(server_url).rstrip("/") != allowed:
        return JSONResponse({"detail": "Invalid server_url."}, status_code=400)

    app_path = _find_god_eyes_app()
    if app_path is None:
        return HTMLResponse(
            "<h3>Không tìm thấy GodEyes.exe trên máy này.</h3>"
            "<p>Hãy cài God Eyes trước rồi thử lại.</p>",
            status_code=404,
        )

    try:
        cmd = [str(app_path), "--server-url", allowed]
        subprocess.Popen(
            cmd,
            cwd=str(app_path.parent),
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            creationflags=getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0),
        )
    except Exception as exc:
        return HTMLResponse(
            f"<h3>Không thể mở God Eyes.</h3><p>{escape(str(exc))}</p>",
            status_code=500,
        )

    return RedirectResponse(
        url=f"{allowed}/teacher?section=app&status=launch_started",
        status_code=303,
    )


