@app.post("/teacher/app/open")
def teacher_open_app(request: Request):
    payload = get_teacher_payload(request)
    if payload is None:
        return RedirectResponse(url="/", status_code=303)

    teacher_id = int(payload["sub"])
    app_path = _find_god_eyes_app()
    if app_path is None:
        return RedirectResponse(url="/teacher?section=app&status=app_missing", status_code=303)

    token = _issue_app_launch_token(teacher_id)
    server_url = str(request.base_url).rstrip('/')
    if app_path.suffix.lower() == '.exe':
        cmd = [str(app_path), '--launch-token', token, '--server-url', server_url]
    else:
        cmd = [sys.executable, str(app_path), '--launch-token', token, '--server-url', server_url]
    try:
        subprocess.Popen(
            cmd,
            cwd=str(app_path.parent),
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            creationflags=getattr(subprocess, 'CREATE_NEW_PROCESS_GROUP', 0),
        )
    except Exception:
        APP_LAUNCH_TOKENS.pop(token, None)
        return RedirectResponse(url="/teacher?section=app&status=launch_error", status_code=303)

    return RedirectResponse(url="/teacher?section=app&status=launch_started", status_code=303)


