@app.post("/api/v1/app/launch/exchange")
async def api_app_launch_exchange(request: Request):
    try:
        body = await request.json()
    except Exception:
        body = {}
    token = str(body.get('token') or '').strip() if isinstance(body, dict) else ''
    if not token:
        return JSONResponse({"detail": "Launch token is required."}, status_code=400)

    _cleanup_app_launch_tokens()
    token_data = APP_LAUNCH_TOKENS.pop(token, None)
    if token_data is None:
        return JSONResponse({"detail": "Launch token is invalid or expired."}, status_code=401)

    teacher_id = api_int(token_data.get('teacher_id'))
    with SessionLocal() as db:
        teacher = db.execute(
            text("SELECT id, username, full_name, is_active FROM teacher_accounts WHERE id = :id LIMIT 1"),
            {"id": teacher_id}
        ).mappings().first()

    if teacher is None or not teacher['is_active']:
        return JSONResponse({"detail": "Teacher account is inactive or not found."}, status_code=403)

    with SessionLocal() as db:
        # The launch token was already consumed above; create the persistent
        # device credential so future direct launches do not need a password.
        device_token = _issue_persistent_device_token(
            db, int(teacher['id']), 'God Eyes Desktop', DESKTOP_APP_VERSION
        )
        db.commit()

    access_token = create_access_token(
        user_id=int(teacher['id']),
        username=teacher['username'],
        role='TEACHER'
    )
    return {
        'access_token': access_token,
        'token_type': 'bearer',
        'username': teacher['username'],
        'role': 'TEACHER',
        'full_name': teacher['full_name'],
        'client_version': DESKTOP_APP_VERSION,
        'device_token': device_token,
    }


