@app.post("/teacher/settings/save")
def teacher_settings_save(
    request: Request,
    language: str = Form("vi"),
    theme: str = Form("light"),
    camera_source: str = Form("webcam"),
    camera_brand: str = Form(""),
    camera_device_index: int = Form(0),
    camera_host: str = Form(""),
    camera_port: int = Form(554),
    camera_stream: str = Form("stream1"),
    camera_username: str = Form(""),
):
    payload = get_teacher_payload(request)
    if payload is None or payload.get('role') != 'TEACHER':
        return RedirectResponse(url="/", status_code=303)
    teacher_id = int(payload['sub'])
    current = get_teacher_preferences(teacher_id)
    save_teacher_preferences(
        teacher_id, language, theme, camera_source,
        camera_brand or current.get('camera_brand', ''),
        camera_device_index,
        camera_host or current.get('camera_host', ''),
        camera_port, camera_stream,
        camera_username or current.get('camera_username', '')
    )
    return RedirectResponse(url="/teacher?section=settings&status=saved", status_code=303)


