# -----------------------------------------------------------------------------
# God Eyes client/server API foundation
# Camera streaming is intentionally kept out of this layer for now.
# The desktop client will use these APIs for class roster, Face ID data,
# session lifecycle, observations, evidence and history.
# -----------------------------------------------------------------------------

SESSION_EVIDENCE_DIR = Path(__file__).resolve().parent.parent / "data" / "evidence"
SESSION_EVIDENCE_DIR.mkdir(parents=True, exist_ok=True)

API_MAX_EVENT_BATCH = 200
API_MAX_EVIDENCE_BYTES = 5 * 1024 * 1024
API_ALLOWED_EVIDENCE_TYPES = {"image/png", "image/jpeg", "image/webp"}
SESSION_STALE_SECONDS = 90


def utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def ensure_session_tables():
    """Create and migrate session/history tables used by the God Eyes desktop client."""
    with SessionLocal() as db:
        db.execute(text("""
            CREATE TABLE IF NOT EXISTS sessions (
                id BIGSERIAL PRIMARY KEY,
                teacher_id INTEGER NOT NULL,
                class_id INTEGER NOT NULL,
                status TEXT NOT NULL DEFAULT 'RUNNING',
                started_at TEXT NOT NULL,
                ended_at TEXT NOT NULL DEFAULT '',
                duration_seconds INTEGER NOT NULL DEFAULT 0,
                client_version TEXT NOT NULL DEFAULT '',
                camera_type TEXT NOT NULL DEFAULT 'WEBCAM',
                last_heartbeat_at TEXT NOT NULL DEFAULT '',
                class_name_snapshot TEXT NOT NULL DEFAULT '',
                class_code_snapshot TEXT NOT NULL DEFAULT '',
                deleted_at TEXT NOT NULL DEFAULT '',
                deleted_by_teacher_id INTEGER NOT NULL DEFAULT 0,
                deleted_by_username TEXT NOT NULL DEFAULT '',
                deleted_from TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP::text
            )
        """))

        db.execute(text("""
            CREATE TABLE IF NOT EXISTS session_students (
                id BIGSERIAL PRIMARY KEY,
                session_id INTEGER NOT NULL,
                student_id INTEGER NOT NULL,
                student_code TEXT NOT NULL,
                full_name TEXT NOT NULL,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP::text,
                UNIQUE(session_id, student_id)
            )
        """))

        db.execute(text("""
            CREATE TABLE IF NOT EXISTS observations (
                id BIGSERIAL PRIMARY KEY,
                session_id INTEGER NOT NULL,
                student_id INTEGER NOT NULL DEFAULT 0,
                student_code TEXT NOT NULL DEFAULT '',
                full_name TEXT NOT NULL DEFAULT '',
                observed_at TEXT NOT NULL,
                event_type TEXT NOT NULL,
                confidence REAL NOT NULL DEFAULT 0,
                assessment TEXT NOT NULL DEFAULT 'OBSERVATION',
                details TEXT NOT NULL DEFAULT '',
                evidence_id INTEGER,
                duration_seconds REAL NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP::text
            )
        """))

        db.execute(text("""
            CREATE TABLE IF NOT EXISTS evidence (
                id BIGSERIAL PRIMARY KEY,
                session_id INTEGER NOT NULL,
                student_id INTEGER NOT NULL DEFAULT 0,
                student_code TEXT NOT NULL DEFAULT '',
                full_name TEXT NOT NULL DEFAULT '',
                captured_at TEXT NOT NULL,
                event_type TEXT NOT NULL DEFAULT 'OBSERVATION',
                confidence REAL NOT NULL DEFAULT 0,
                file_name TEXT NOT NULL,
                file_path TEXT NOT NULL,
                mime_type TEXT NOT NULL DEFAULT 'image/jpeg',
                width INTEGER NOT NULL DEFAULT 0,
                height INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP::text
            )
        """))

        # Observation duration is optional for backward compatibility with older clients.
        observation_columns = _table_columns(db, "observations")
        if "duration_seconds" not in observation_columns:
            db.execute(text("ALTER TABLE observations ADD COLUMN duration_seconds REAL NOT NULL DEFAULT 0"))
        if "focus_score" not in observation_columns:
            db.execute(text("ALTER TABLE observations ADD COLUMN focus_score REAL"))

        # Existing sessions table migration.
        session_columns = _table_columns(db, "sessions")

        session_migrations = {
            "last_heartbeat_at":
                "ALTER TABLE sessions ADD COLUMN last_heartbeat_at TEXT NOT NULL DEFAULT ''",
            "class_name_snapshot":
                "ALTER TABLE sessions ADD COLUMN class_name_snapshot TEXT NOT NULL DEFAULT ''",
            "class_code_snapshot":
                "ALTER TABLE sessions ADD COLUMN class_code_snapshot TEXT NOT NULL DEFAULT ''",
            "deleted_at":
                "ALTER TABLE sessions ADD COLUMN deleted_at TEXT NOT NULL DEFAULT ''",
            "deleted_by_teacher_id":
                "ALTER TABLE sessions ADD COLUMN deleted_by_teacher_id INTEGER NOT NULL DEFAULT 0",
            "deleted_by_username":
                "ALTER TABLE sessions ADD COLUMN deleted_by_username TEXT NOT NULL DEFAULT ''",
            "deleted_from":
                "ALTER TABLE sessions ADD COLUMN deleted_from TEXT NOT NULL DEFAULT ''",
        }

        for column, statement in session_migrations.items():
            if column not in session_columns:
                db.execute(text(statement))

        # Existing PostgreSQL databases may already contain an older
        # session_students table without the columns required by the
        # current INSERT in /api/v1/sessions.
        session_student_columns = _table_columns(db, "session_students")

        if "student_code" not in session_student_columns:
            db.execute(text("""
                ALTER TABLE session_students
                ADD COLUMN student_code TEXT NOT NULL DEFAULT ''
            """))

        if "full_name" not in session_student_columns:
            db.execute(text("""
                ALTER TABLE session_students
                ADD COLUMN full_name TEXT NOT NULL DEFAULT ''
            """))

        # Backfill session metadata.
        db.execute(text("""
            UPDATE sessions
            SET last_heartbeat_at = started_at
            WHERE last_heartbeat_at = ''
               OR last_heartbeat_at IS NULL
        """))

        db.execute(text("""
            UPDATE sessions
            SET class_name_snapshot = COALESCE(
                (
                    SELECT name
                    FROM classes
                    WHERE classes.id = sessions.class_id
                ),
                class_name_snapshot
            )
            WHERE class_name_snapshot = ''
               OR class_name_snapshot IS NULL
        """))

        db.execute(text("""
            UPDATE sessions
            SET class_code_snapshot = COALESCE(
                (
                    SELECT code
                    FROM classes
                    WHERE classes.id = sessions.class_id
                ),
                class_code_snapshot
            )
            WHERE class_code_snapshot = ''
               OR class_code_snapshot IS NULL
        """))

        db.execute(text("""
            CREATE INDEX IF NOT EXISTS idx_sessions_teacher
            ON sessions(teacher_id, deleted_at, id DESC)
        """))

        db.execute(text("""
            CREATE INDEX IF NOT EXISTS idx_sessions_class
            ON sessions(class_id, deleted_at, id DESC)
        """))

        db.execute(text("""
            CREATE INDEX IF NOT EXISTS idx_sessions_deleted
            ON sessions(deleted_at, id DESC)
        """))

        db.execute(text("""
            CREATE INDEX IF NOT EXISTS idx_session_students_session
            ON session_students(session_id)
        """))

        db.execute(text("""
            CREATE INDEX IF NOT EXISTS idx_observations_session
            ON observations(session_id, id DESC)
        """))

        db.execute(text("""
            CREATE INDEX IF NOT EXISTS idx_evidence_session
            ON evidence(session_id, id DESC)
        """))

        db.commit()


# Run the session/history schema migration at application startup.
# This is required for existing PostgreSQL databases where observations
# was created by an older build without duration_seconds.
ensure_session_tables()


def api_teacher_or_401(request: Request):
    payload = get_teacher_payload(request)
    if payload is None:
        return None
    return payload


@app.get("/api/v1/teacher/preferences")
def api_get_teacher_preferences(request: Request):
    payload = api_teacher_or_401(request)
    if payload is None:
        return JSONResponse({"detail": "Teacher authentication required."}, status_code=401)
    return get_teacher_preferences(int(payload['sub']))


@app.post("/api/v1/teacher/preferences")
async def api_save_teacher_preferences(request: Request):
    payload = api_teacher_or_401(request)
    if payload is None:
        return JSONResponse({"detail": "Teacher authentication required."}, status_code=401)
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not isinstance(body, dict):
        body = {}
    current = get_teacher_preferences(int(payload['sub']))
    prefs = save_teacher_preferences(
        int(payload['sub']),
        body.get('language', current['language']),
        body.get('theme', current['theme']),
        body.get('camera_source', current['camera_source']),
        body.get('camera_brand', current.get('camera_brand', '')),
        body.get('camera_device_index', current['camera_device_index']),
        body.get('camera_host', current['camera_host']),
        body.get('camera_port', current['camera_port']),
        body.get('camera_stream', current['camera_stream']),
        body.get('camera_username', current['camera_username']),
    )
    return prefs


@app.get("/api/v1/cameras")
def api_list_main_cameras(request: Request):
    payload = api_teacher_or_401(request)
    if payload is None:
        return JSONResponse({"detail": "Teacher authentication required."}, status_code=401)
    with SessionLocal() as db:
        main_id = _get_main_account_id(db)
        if main_id <= 0:
            return JSONResponse({"detail": "Main account not found."}, status_code=500)
        rows = db.execute(
            text("SELECT id,name,brand,model,source_type,device_id,host,port,stream,username,last_verified_at,password_enc FROM main_camera_profiles WHERE main_account_id=:mid AND is_active=1 ORDER BY id DESC"),
            {"mid": main_id}
        ).mappings().all()
    items=[_camera_profile_dict(row, include_url=True) for row in rows]
    return {"items": items}


@app.post("/api/v1/cameras")
async def api_add_main_camera(request: Request):
    payload = api_teacher_or_401(request)
    if payload is None:
        return JSONResponse({"detail": "Teacher authentication required."}, status_code=401)
    try: body = await request.json()
    except Exception: body = {}
    if not isinstance(body, dict): body = {}
    data = _normalise_main_camera_payload(body)
    if data["source_type"] == "wifi_camera":
        if not data["host"] or not data["username"] or not data["password"]:
            return JSONResponse({"detail": "Camera host, username and password are required for a Wi-Fi camera."}, status_code=400)
    if not data["name"]:
        model = data["model"] or data["brand"] or "Wi-Fi Camera"
        data["name"] = model
    teacher_id = api_int(payload.get("sub"))
    with SessionLocal() as db:
        main_id = _get_main_account_id(db)
        if main_id <= 0:
            return JSONResponse({"detail": "Main account not found."}, status_code=500)
        now = utc_now_iso()
        # Update the existing profile when the same device endpoint/account is already known.
        existing = db.execute(text("SELECT id FROM main_camera_profiles WHERE main_account_id=:mid AND brand=:brand AND host=:host AND username=:username AND is_active=1 ORDER BY id DESC LIMIT 1"), {"mid":main_id,"brand":data["brand"],"host":data["host"],"username":data["username"]}).first()
        if existing:
            cam_id=int(existing[0])
            db.execute(text("""
                UPDATE main_camera_profiles
                SET name=:name, model=:model, source_type=:source_type, device_id=:device_id,
                    port=:port, stream=:stream, password_enc=:password_enc,
                    last_verified_at=:verified, updated_at=:updated, is_active=1
                WHERE id=:id AND main_account_id=:mid
            """), {"name":data["name"],"model":data["model"],"source_type":data["source_type"],"device_id":data["device_id"],"port":data["port"],"stream":data["stream"],"password_enc":_encrypt_camera_secret(data["password"]),"verified":now,"updated":now,"id":cam_id,"mid":main_id})
        else:
            result=db.execute(text("""
                INSERT INTO main_camera_profiles
                    (main_account_id,name,brand,model,source_type,device_id,host,port,stream,username,password_enc,last_verified_at,created_at,updated_at)
                VALUES
                    (:mid,:name,:brand,:model,:source_type,:device_id,:host,:port,:stream,:username,:password_enc,:verified,:created,:updated)
                RETURNING id
            """), {"mid":main_id,**{k:data[k] for k in ("name","brand","model","source_type","device_id","host","port","stream","username")},"password_enc":_encrypt_camera_secret(data["password"]),"verified":now,"created":now,"updated":now})
            cam_id=int(result.scalar_one())
        db.commit()
        row=db.execute(text("SELECT id,name,brand,model,source_type,device_id,host,port,stream,username,last_verified_at,password_enc FROM main_camera_profiles WHERE id=:id AND main_account_id=:mid"), {"id":cam_id,"mid":main_id}).mappings().first()
    return _camera_profile_dict(row, include_url=True)


@app.post("/api/v1/cameras/{camera_id}/touch")
def api_touch_main_camera(request: Request, camera_id: int):
    payload = api_teacher_or_401(request)
    if payload is None:
        return JSONResponse({"detail": "Teacher authentication required."}, status_code=401)
    with SessionLocal() as db:
        main_id=_get_main_account_id(db)
        db.execute(text("UPDATE main_camera_profiles SET last_verified_at=:now, updated_at=:now WHERE id=:id AND main_account_id=:mid AND is_active=1"), {"now":utc_now_iso(),"id":int(camera_id),"mid":main_id})
        db.commit()
    return {"ok": True}


def api_int(value, default=0):
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def get_teacher_class(db, teacher_id: int, class_id: int):
    return db.execute(
        text("""
            SELECT id, name, code, description
            FROM classes
            WHERE id = :class_id
              AND owner_type = 'TEACHER'
              AND owner_id = :teacher_id
            LIMIT 1
        """),
        {"class_id": class_id, "teacher_id": teacher_id}
    ).mappings().first()


def get_session_for_teacher(db, teacher_id: int, session_id: int):
    return db.execute(
        text("""
            SELECT id, teacher_id, class_id, status, started_at, ended_at,
                   duration_seconds, client_version, camera_type, last_heartbeat_at,
                   class_name_snapshot, class_code_snapshot,
                   deleted_at, deleted_by_teacher_id, deleted_by_username, deleted_from,
                   created_at
            FROM sessions
            WHERE id = :session_id
              AND teacher_id = :teacher_id
              AND COALESCE(deleted_at, '') = ''
            LIMIT 1
        """),
        {"session_id": session_id, "teacher_id": teacher_id}
    ).mappings().first()


def session_roster(db, session_id: int):
    rows = db.execute(
        text("""
            SELECT student_id, student_code, full_name
            FROM session_students
            WHERE session_id = :session_id
            ORDER BY id ASC
        """),
        {"session_id": session_id}
    ).mappings().all()
    return [dict(row) for row in rows]


def class_face_roster(db, class_id: int):
    rows = db.execute(
        text("""
            SELECT s.id, s.student_code, s.full_name, s.face_status, s.face_embedding
            FROM students s
            JOIN class_students cs ON cs.student_id = s.id
            WHERE cs.class_id = :class_id
            ORDER BY s.id ASC
        """),
        {"class_id": class_id}
    ).mappings().all()

    roster = []
    for row in rows:
        embedding = None
        raw = row["face_embedding"] or ""
        if row["face_status"] == "READY" and raw:
            try:
                parsed = json.loads(raw)
                if isinstance(parsed, list) and parsed:
                    embedding = parsed
            except Exception:
                embedding = None

        roster.append({
            "id": int(row["id"]),
            "student_code": row["student_code"],
            "full_name": row["full_name"],
            "face_status": row["face_status"],
            "face_embedding": embedding,
            "ready": embedding is not None,
        })
    return roster


def student_snapshot(db, class_id: int):
    rows = db.execute(
        text("""
            SELECT s.id, s.student_code, s.full_name
            FROM students s
            JOIN class_students cs ON cs.student_id = s.id
            WHERE cs.class_id = :class_id
            ORDER BY s.id ASC
        """),
        {"class_id": class_id}
    ).mappings().all()
    return [dict(row) for row in rows]


def safe_evidence_suffix(mime_type: str) -> str:
    return {
        "image/png": ".png",
        "image/webp": ".webp",
        "image/jpeg": ".jpg",
    }.get(mime_type, ".jpg")


