@app.post("/api/v1/face-enrollment")
async def api_face_enrollment(request: Request):
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"detail": "Invalid JSON body."}, status_code=400)

    if not isinstance(body, dict):
        return JSONResponse({"detail": "Invalid JSON body."}, status_code=400)

    token = str(body.get("token") or "").strip()
    student_id = api_int(body.get("student_id"))
    embedding = body.get("embedding")

    if not token or student_id <= 0 or not isinstance(embedding, list):
        return JSONResponse(
            {"detail": "Missing enrollment token, student_id or embedding."},
            status_code=400,
        )

    _cleanup_face_scan_tokens()
    token_data = FACE_SCAN_TOKENS.get(token)

    if token_data is None:
        return JSONResponse(
            {"detail": "Enrollment token is invalid or expired."},
            status_code=401,
        )

    if int(token_data.get("student_id", 0)) != int(student_id):
        return JSONResponse(
            {"detail": "Enrollment token does not match the student."},
            status_code=403,
        )

    try:
        values = [float(v) for v in embedding]
    except Exception:
        return JSONResponse(
            {"detail": "Embedding contains invalid values."},
            status_code=400,
        )

    if len(values) < 32 or len(values) > 4096:
        return JSONResponse(
            {"detail": f"Embedding length is invalid: {len(values)}."},
            status_code=400,
        )

    values_array = np.asarray(values, dtype=np.float32)

    if not np.all(np.isfinite(values_array)):
        return JSONResponse(
            {"detail": "Embedding contains non-finite values."},
            status_code=400,
        )

    vector = values_array.reshape(-1)
    norm = float(np.linalg.norm(vector))

    if norm <= 1e-8:
        return JSONResponse(
            {"detail": "Embedding norm is invalid."},
            status_code=400,
        )

    vector = vector / norm
    serialized = json.dumps(vector.tolist(), ensure_ascii=False, separators=(",", ":"))

    db = None

    try:
        db = SessionLocal()

        row = db.execute(
            text("""
                SELECT id, full_name, student_code
                FROM students
                WHERE id = :student_id
                LIMIT 1
            """),
            {"student_id": student_id},
        ).mappings().first()

        if row is None:
            db.rollback()
            return JSONResponse({"detail": "Student not found."}, status_code=404)

        result = db.execute(
            text("""
                UPDATE students
                SET face_embedding = :face_embedding,
                    face_status = 'READY'
                WHERE id = :student_id
            """),
            {
                "face_embedding": serialized,
                "student_id": student_id,
            },
        )

        if result.rowcount != 1:
            db.rollback()
            return JSONResponse(
                {
                    "detail": (
                        "Face ID save failed: "
                        f"student update affected {result.rowcount} rows."
                    )
                },
                status_code=500,
            )

        db.commit()

    except Exception as exc:
        if db is not None:
            try:
                db.rollback()
            except Exception:
                pass

        return JSONResponse(
            {
                "detail": (
                    "Face ID database save failed: "
                    f"{type(exc).__name__}: {exc}"
                )
            },
            status_code=500,
        )

    finally:
        if db is not None:
            try:
                db.close()
            except Exception:
                pass

    FACE_SCAN_TOKENS.pop(token, None)

    return {
        "success": True,
        "student_id": int(student_id),
        "student_code": row["student_code"],
        "full_name": row["full_name"],
        "face_status": "READY",
    }

